package android.app;
public class FragmentTransaction { private final FragmentManager manager; FragmentTransaction(FragmentManager m) { manager=m; } public FragmentTransaction add(Fragment f,String tag) { manager.add(tag,f); return this; } public FragmentTransaction add(int id,Fragment f) { manager.add(String.valueOf(id),f); return this; } public FragmentTransaction add(int id,Fragment f,String tag) { manager.add(tag,f); return this; } public FragmentTransaction replace(int id,Fragment f) { return add(id,f); } public FragmentTransaction replace(int id,Fragment f,String tag) { return add(id,f,tag); } public FragmentTransaction remove(Fragment f) { manager.remove(f); return this; } public FragmentTransaction addToBackStack(String name) { return this; } public int commit() { return 0; } public int commitAllowingStateLoss() { return 0; } public void commitNow() {} public void commitNowAllowingStateLoss() {} }
